import { SIDEBAR_WIDTH } from './appNavigation';

/** Horizontal padding for main content and header rows that sit above it. */
export const APP_CONTENT_GUTTER = { xs: 2, md: 3 } as const;

/**
 * Left inset for full-width header rows (breadcrumbs, page banner) so they line up
 * with the main column when the desktop sidebar is visible.
 */
export function headerMainColumnInsetSx(showSidebar: boolean) {
  if (!showSidebar) {
    return { px: APP_CONTENT_GUTTER };
  }

  return {
    pl: {
      xs: APP_CONTENT_GUTTER.xs,
      md: `calc(${SIDEBAR_WIDTH}px + 24px)`,
    },
    pr: APP_CONTENT_GUTTER,
  };
}

export { SIDEBAR_WIDTH };
